class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const mkTable = () => ({ t: 'table', m: new Map(), hdr: false })
const BARE = /[A-Za-z0-9_-]/
const D = '[0-9]+(?:_[0-9]+)*'
const INT = new RegExp(`^[+-]?${D}$`)
const FLOAT = new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`)

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++ }
  end() {
    this.ws()
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  quoted() {
    const q = this.s[this.i++]
    let out = ''
    for (;;) {
      const c = this.s[this.i]
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === q) return out
      if (q === "'" || c !== '\\') { out += c; continue }
      const e = this.s[this.i]
      if (e === undefined) fail('unterminated string')
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        this.i += 4
        out += String.fromCharCode(parseInt(h, 16))
      } else fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0)))
    }
  }
  name() {
    this.ws()
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.quoted()
    const st = this.i
    while (this.i < this.s.length && BARE.test(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      this.ws()
      if (this.s[this.i] !== '.') return parts
      this.i++
      parts.push(this.name())
    }
  }
  value(base) {
    if (this.end()) fail('expected a value')
    const c = this.s[this.i]
    if (c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < this.s.length && !' \t,]};'.includes(this.s[this.i])) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    if (INT.test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }
  array(base) {
    this.i++
    const items = []
    for (;;) {
      if (this.end()) fail('unterminated array')
      if (this.s[this.i] === ']') { this.i++; break }
      items.push(this.value(base))
      if (this.end()) fail('unterminated array')
      const c = this.s[this.i]
      if (c === ',') { this.i++; continue }
      if (c === ']') { this.i++; break }
      fail('unterminated array')
    }
    return { t: 'array', items, aot: false }
  }
  inline(base) {
    this.i++
    const tbl = mkTable()
    if (this.end()) fail('unterminated inline table')
    if (this.s[this.i] === '}') { this.i++; return tbl }
    for (;;) {
      if (this.end()) fail('unterminated inline table')
      const keys = this.dotted()
      if (this.end() || this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      const full = base.concat(keys)
      const v = this.value(full)
      assign(tbl, keys, v, base)
      if (this.end()) fail('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') { this.i++; continue }
      if (c === '}') { this.i++; return tbl }
      fail('unterminated inline table')
    }
  }
}

const P = (a) => a.join('.')

// Walk `keys` below `cur`, creating tables; returns the table reached.
function walk(cur, keys, base) {
  let path = base.slice()
  for (const k of keys) {
    path.push(k)
    let n = cur.m.get(k)
    if (n === undefined) { n = mkTable(); cur.m.set(k, n) }
    if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    if (n.t !== 'table') fail(`${P(path)} is not a table`)
    cur = n
  }
  return cur
}

function assign(cur, keys, v, base) {
  const t = walk(cur, keys.slice(0, -1), base)
  const last = keys[keys.length - 1]
  if (t.m.has(last)) fail(`key ${P(base.concat(keys))} is defined twice`)
  t.m.set(last, v)
}

function header(root, keys, isArr) {
  const parent = walk(root, keys.slice(0, -1), [])
  const last = keys[keys.length - 1]
  const n = parent.m.get(last)
  if (isArr) {
    if (n === undefined) {
      const t = mkTable()
      parent.m.set(last, { t: 'array', items: [t], aot: true })
      return t
    }
    if (n.t !== 'array' || !n.aot) fail(`${P(keys)} is not an array of tables`)
    const t = mkTable()
    n.items.push(t)
    return t
  }
  if (n === undefined) {
    const t = mkTable()
    t.hdr = true
    parent.m.set(last, t)
    return t
  }
  if (n.t !== 'table') fail(`${P(keys)} is not a table`)
  if (n.hdr) fail(`table ${P(keys)} is defined twice`)
  n.hdr = true
  return n
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = mkTable()
  let cur = root
  let curPath = []
  lines.forEach((line, idx) => {
    try {
      const p = new LineParser(line)
      if (p.end()) return
      if (line[p.i] === '[') {
        p.i++
        const isArr = line[p.i] === '['
        if (isArr) p.i++
        const keys = p.dotted()
        p.ws()
        if (line[p.i] !== ']') fail('unterminated table header')
        p.i++
        if (isArr) {
          if (line[p.i] !== ']') fail('unterminated table header')
          p.i++
        }
        if (!p.end()) fail('trailing text after a table header')
        cur = header(root, keys, isArr)
        curPath = keys
        return
      }
      const keys = p.dotted()
      p.ws()
      if (line[p.i] !== '=') fail('expected key = value')
      p.i++
      const v = p.value(curPath.concat(keys))
      if (!p.end()) fail('trailing text after a value')
      assign(cur, keys, v, curPath)
    } catch (e) {
      if (e instanceof Fail) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  switch (n.t) {
    case 'table': {
      const ks = sortedKeys(n.m)
      if (!ks.length) return '{}'
      return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(n.m.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
    }
    case 'array':
      if (!n.items.length) return '[]'
      return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
    case 'integer': return n.v.toString()
    default: return JSON.stringify(n.v)
  }
}

function keysOut(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n.m)) {
      const c = n.m.get(k)
      const p = path === null ? k : path + '.' + k
      out.push(`${p} ${c.t}`)
      keysOut(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.t}`)
      keysOut(c, p, out)
    })
  }
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'json' && mode !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
try {
  const root = parse(readFileSync(0, 'utf8'))
  if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
  else {
    const out = []
    keysOut(root, null, out)
    process.stdout.write(out.map((l) => l + '\n').join(''))
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
"}

